/* eslint-disable @typescript-eslint/no-var-requires */
/**
 * Expo config plugin: installs the native MediaScanner module (Android).
 *
 * The android/ folder is generated by `expo prebuild` (and gitignored), so any
 * native code placed there by hand is lost on EAS/clean builds. This plugin
 * re-adds it on every prebuild:
 *   1. copies MediaScannerModule.kt + MediaScannerPackage.kt into the app package
 *   2. registers MediaScannerPackage in MainApplication.kt
 *
 * JS side: src/services/mediaScannerService.ts (NativeModules.MediaScannerModule).
 */
const fs = require('fs')
const path = require('path')
const { withDangerousMod, withMainApplication } = require('expo/config-plugins')

const SOURCE_DIR = path.join(__dirname, 'android')
const FILES = ['MediaScannerModule.kt', 'MediaScannerPackage.kt']

function getPackageName(config) {
	const name = config.android && config.android.package
	if (!name) {
		throw new Error('withMediaScanner: "android.package" must be set in app.json')
	}
	return name
}

const withMediaScannerSources = (config) =>
	withDangerousMod(config, [
		'android',
		(cfg) => {
			const pkg = getPackageName(cfg)
			const targetDir = path.join(
				cfg.modRequest.platformProjectRoot,
				'app',
				'src',
				'main',
				'java',
				...pkg.split('.')
			)
			fs.mkdirSync(targetDir, { recursive: true })

			for (const file of FILES) {
				// The sources are written against com.music.player; rewrite the
				// package line if the app id ever changes.
				const source = fs
					.readFileSync(path.join(SOURCE_DIR, file), 'utf8')
					.replace(/^package\s+[\w.]+/m, `package ${pkg}`)
				fs.writeFileSync(path.join(targetDir, file), source)
			}
			return cfg
		},
	])

const withMediaScannerRegistration = (config) =>
	withMainApplication(config, (cfg) => {
		const mod = cfg.modResults
		if (mod.language !== 'kt') {
			throw new Error('withMediaScanner: expected a Kotlin MainApplication')
		}
		if (mod.contents.includes('MediaScannerPackage()')) {
			return cfg
		}

		const pattern = /(PackageList\(this\)\.packages\.apply\s*\{)/
		if (!pattern.test(mod.contents)) {
			throw new Error(
				'withMediaScanner: could not find "PackageList(this).packages.apply {" in MainApplication.kt. ' +
					'The Expo template changed - update plugins/withMediaScanner.js.'
			)
		}
		mod.contents = mod.contents.replace(pattern, '$1\n          add(MediaScannerPackage())')
		return cfg
	})

module.exports = (config) => withMediaScannerRegistration(withMediaScannerSources(config))
